// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNumber) public {
        vm.assume(blockNumber > 0);
        vm.roll(blockNumber);
        address sender = address(0x12345);
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool ok,) = address(c).call{value: 10 ether}("");
        require(ok, "call failed");
        bool balanceIsZero = address(c).balance == 0;
        if (blockNumber % 15 == 0) {
            assertTrue(balanceIsZero);
        } else {
            assertTrue(!balanceIsZero);
        }
    }
}
